-- =============================================================
-- MediVault -- Test Data (Portuguese)
-- Compatible with SQL Server, SQLite, MySQL, PostgreSQL
-- Note: booleans use 1/0 (SQL Server/SQLite) — for PostgreSQL
--       replace with TRUE/FALSE; MySQL accepts both.
-- Note: users.id, doctors.id and institutions.id are fixed GUIDs
--       (literals), to keep relationships deterministic across
--       dialects. Normally generated by the application (Guid.NewGuid()).
-- =============================================================

-- -------------------------------------------------------
-- SUBSCRIPTION_PLANS
-- -------------------------------------------------------

-- -------------------------------------------------------
-- INSTITUTIONS
-- id: fixed GUID (10000000-0000-0000-0000-00000000000X)
-- -------------------------------------------------------

-- -------------------------------------------------------
-- VACCINES (National Vaccination Programme - PNV)
-- -------------------------------------------------------

-- -------------------------------------------------------
-- ICPC2_CODES (sample of relevant codes)
-- -------------------------------------------------------

-- -------------------------------------------------------
-- MEDICAL_SPECIALTIES
-- -------------------------------------------------------

-- -------------------------------------------------------
-- GENDERS (config table — code matches the former CHECK constraint)
-- id 1=M, 2=F, 3=Other
-- -------------------------------------------------------

-- -------------------------------------------------------
-- HABIT_TYPES (config table — code matches the former CHECK constraint)
-- id 1=alcohol, 2=tobacco, 3=drugs, 4=gambling, 5=physical_activity
-- -------------------------------------------------------

-- -------------------------------------------------------
-- RELATIONSHIP_TYPES (config table — code matches the former CHECK constraint)
-- id 1=parent, 2=legal_guardian, 3=tutor, 4=other
-- -------------------------------------------------------

-- -------------------------------------------------------
-- COUNTRIES (config table)
-- Full ISO 3166-1 list (alpha-3 code), sorted alphabetically
-- by the Portuguese name.
-- Used in the seeds below: Portugal id=184, Brasil id=30, Espanha id=66
-- -------------------------------------------------------

